// Nineteen comparable horizons arranged as nine legal binary pairs plus a
// central reference. Binary centers are prescribed, not an N-body solution.
const hierarchyRg=1476.62504,clusterOrbitUnit=hierarchyRg*30e6;
function horizonHierarchy(){
 const bodies=[],names=['Aurelia','Iris','Cinder','Vesper','Lyra','Orion','Nacre','Sable','Astra'];
 const masses=[28.5,30.6,29.1,31.4,27.9,32.0,28.8,30.2,31.1],radii=[74,92,82,100,86,96,78,104,46];
 const phases=[.10,.83,1.59,2.31,3.03,3.84,4.60,5.43,2.9],heights=[-8,12,-14,6,17,-9,9,-17,24];
 for(let i=0;i<9;i++){
  const key='cluster-'+i,mass=masses[i]*1e6,phase=phases[i];
  const root={key,type:'blackhole',name:names[i]+' A',parentId:'space',placement:'local',massSolar:mass,
   x:Math.cos(phase)*radii[i]*clusterOrbitUnit,y:heights[i]*clusterOrbitUnit,z:Math.sin(phase)*radii[i]*clusterOrbitUnit,
   axialTilt:-32+i*8,phase};
  const companion={key:key+'-b',type:'blackhole',name:names[i]+' B',parentKey:key,massSolar:mass*(i%2?1.035:.965),
   orbitMeters:(24+i*.7)*clusterOrbitUnit,eccentricity:.05+(i%4)*.025,phase:phase+1.1+i*.49,
   orbitInclination:-48+i*12,orbitNode:19+i*41,argumentPeriapsis:34+i*37,axialTilt:37-i*7};
  bodies.push(root,companion);
 }
 return bodies;
}
// Fixed star separations in metres; planetary phases illustrate a coplanar tour,
