const LIGHT_YEAR=299792458*365.25*86400,PARSEC=AU_METERS*648000/Math.PI;
const interstellarHome=solarSystemBodies.filter(o=>['sun','earth','nasa-shuttle'].includes(o.key)).map(o=>{
 if(o.key==='sun')return {...o,x:0,y:0,z:0};
 return {...o,orbitReferenceFrame:'ecliptic',orbitInclination:0,orbitNode:0,argumentPeriapsis:0,eccentricity:0,
  ...(o.key==='earth'?{phase:Math.PI/2,orbitMeters:AU_METERS}:{orbitMeters:6371000*1.1})};
});
