 ...interstellarHome.map(o=>o.key==='nasa-shuttle'?{...o,key:'ncc-1701',type:'enterprise',hullModel:'classicEnterprise',name:'USS Enterprise',massSolar:undefined,dataNote:'Constitution-class starship NCC-1701.'}:o),
