const fleetBySize=DRIVABLE_HULLS.map(h=>({...h,length:fleetLengths[h.model]??OBJECT_DIMENSIONS[h.model].lengthMeters})).sort((a,b)=>a.length-b.length);
const parkingGap=.42*meridianLength;
const fleetWidth=fleetBySize.reduce((sum,h)=>sum+h.length,parkingGap*(fleetBySize.length-1));
const lineupCamera={fleetOverview:true,distanceMeters:1.14*fleetWidth,yaw:0,pitch:.62};
let parkingEdge=-fleetWidth/2;
