function makePreset(id){const p=SCENE_PRESETS.find(x=>x.id===id)||SCENE_PRESETS[0],state={...DEFAULTS,...p.patch};for(const key of ['disk','diskStyle','diskPalette','diskColor','diskOuter','diskThickness','diskDensity','jets','jetStructure','jetColor','jetSpread','jetLength','jetIntensity']){const secondary='secondary'+key[0].toUpperCase()+key.slice(1);if(!Object.hasOwn(p.patch,secondary))state[secondary]=state[key];}return state;}
function horizonRg(spin){return 1+Math.sqrt(Math.max(0,1-spin*spin));}
